DECLARE @capability_id nvarchar(400)=NULLIF(LTRIM(RTRIM(JSON_VALUE(@input,'$.capabilityId'))),N'');
DECLARE @document_digest varchar(64)=NULL;
IF @capability_id IS NOT NULL
 SELECT TOP 1 @document_digest=LOWER(JSON_VALUE(d.definition_json,'$.semantics.document_digest'))
 FROM analysis.v_selected_semantic_definition d
 WHERE d.estate_model_pk=@estate_model_pk AND d.object_kind='CAPABILITY_DOCUMENT'
  AND d.namespace_id=N'sidefx:capability-documents' AND d.declared_id=@capability_id COLLATE Latin1_General_100_BIN2;
DECLARE @document nvarchar(max)=NULL;
IF @document_digest IS NOT NULL
 SELECT @document=CONVERT(nvarchar(max),CONVERT(varchar(max),co.content_bytes) COLLATE Latin1_General_100_BIN2_UTF8)
 FROM source.content_object co WHERE co.content_digest=CONVERT(binary(32),@document_digest,2);
SELECT (SELECT @capability_id AS capabilityId,
 CONVERT(bit,CASE WHEN @document_digest IS NULL THEN 0 ELSE 1 END) AS documentInstalled,
 CASE WHEN @document_digest IS NULL THEN NULL ELSE N'sha256:'+@document_digest END AS documentDigest,
 JSON_QUERY(@document) AS document
 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) AS value
